head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil30603";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil30603.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "btn_modify", fn: function(){ return ((dma_lecrDiptList.get("lecrDiptProcsStatCd") ?? (() => { throw new Error("unresolved:" + "lecrDiptList.lecrDiptProcsStatCd"); })()) === ''); } }, { id: "btn_modify_2", fn: function(){ return ((dma_lecrDiptList.get("lecrDiptProcsStatCd") ?? (() => { throw new Error("unresolved:" + "lecrDiptList.lecrDiptProcsStatCd"); })()) === '40'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

// [A] 초기 목록 미해결 — jldfil30603: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_modify_onclick
 * @description 「수정」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_modify_onclick = async function(e){
    try {
        await scwin.modify('' + dma_lecrDiptList.get("eduApplSeq") + '')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil30603.btn_modify_onclick' }); }
};

/**
 * @method
 * @name btn_modify_2_onclick
 * @description 「수정」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_modify_2_onclick = async function(e){
    try {
        await scwin.modify('' + dma_lecrDiptList.get("eduApplSeq") + '')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil30603.btn_modify_2_onclick' }); }
};

/**
 * @method
 * @name btn_goList_onclick
 * @description 「목록」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_goList_onclick = async function(e){
    try {
        await scwin.goList()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil30603.btn_goList_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_goList
 * @description go List 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_goList = async function (action) {
    const sbmOptions = {
        id: "tx_fn_goList",
        method: "post",
        action: action ?? "/issue/lecrDipt.do",
        ref: "dma_goListReq",
        target: "dlt_lecrDiptSchdl=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_modify
 * @description modify 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_modify = async function (action) {
    const sbmOptions = {
        id: "tx_fn_modify",
        method: "post",
        action: action ?? "/issue/lecrDipt.do",
        ref: "dma_modifyReq",
        target: "dlt_lecrDiptSchdl=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name goList
 * @description go List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goList = async function () {
    $c.util.getComponent('dma_goListReq').set('method', 'searchLecrDipt');
    const nr = await scwin.tx_fn_goList('lecrDipt.do');
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil30601/jldfil30601.xml", { "method": 'searchLecrDipt' });
    }
};

/**
 * @method
 * @name modify
 * @description modify 처리
 * @param {*} eduApplSeq eduApplSeq
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.modify = async function (eduApplSeq) {
    $c.util.getComponent('dma_goListReq').set('method', 'modifyLecrDipt');
    $c.util.getComponent('dma_goListReq').set('modifyYn', 'Y');
    $c.util.getComponent('dma_goListReq').set('eduApplSeq', eduApplSeq);
    const nr = await scwin.tx_fn_modify('lecrDipt.do');
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil30604/jldfil30604.xml", { "method": 'modifyLecrDipt', "modifyYn": 'Y', "eduApplSeq": eduApplSeq });
    }
};
